    src = [row[:] for row in grid]
    out = [row[:] for row in src]
    crosses = []

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (src[r - 1][c] == 3 and src[r + 1][c] == 3 and
                src[r][c - 1] == 3 and src[r][c + 1] == 3):
                crosses.append((r, c, src[r][c]))

    def extend(r, c, color, dr, dc):
        # Skip the cross's own 3 arm, then continue until another 3 marker.
        rr, cc = r + 2 * dr, c + 2 * dc
        while 0 <= rr < h and 0 <= cc < w and src[rr][cc] != 3:
            out[rr][cc] = color
            rr += dr
            cc += dc

    # Horizontal rays (including the zero-colored cross) are laid down first.
    for r, c, color in crosses:
        extend(r, c, color, 0, -1)
        extend(r, c, color, 0, 1)

    # Vertical rays are drawn afterward, so they overwrite horizontal rays.
    for r, c, color in crosses:
        extend(r, c, color, -1, 0)
        extend(r, c, color, 1, 0)

    # Keep all original marker cells unchanged.
    for r in range(h):
        for c in range(w):
            if src[r][c] == 3:
                out[r][c] = 3

    return out
